(function(){
  var cards=[].slice.call(document.querySelectorAll("div.listings-seller-details-component"));
  var out=[];
  for(var i=0;i<cards.length;i++){
    var c=cards[i];
    var a=c.querySelector("a[href*='/freelancers/'],a[href*='/agencies/']");
    var all=(c.innerText||"").replace(/\s+/g," ").trim();
    var rm=all.match(/([0-9.]+)\s*\(([0-9,]+)\)/);
    var nameEl=c.querySelector(".online-circle-and-seller-name-container");
    var name=nameEl?(nameEl.innerText||"").replace(/\s+/g," ").trim():"";
    if(!name){var m=all.match(/^[A-Z]?\s*(.+?)\s+(?:Vetted Pro|FIVERR'S CHOICE|Level \d|New\b)/);name=m?m[1].trim():"";}
    var headline="";
    var hd=c.querySelector(".m-b-4 > div");
    if(hd)headline=(hd.innerText||"").replace(/\s+/g," ").trim();
    var href=a?String(a.getAttribute("href")).split("?")[0]:"";
    out.push({
      name:name,
      rating:rm?rm[1]:"",
      reviews:rm?rm[2].replace(/,/g,""):"",
      badge:/Vetted Pro/.test(all)?"Vetted Pro":(/FIVERR'S CHOICE/.test(all)?"Fiverr's Choice":""),
      type:/\/agencies\//.test(href)?"agency":"freelancer",
      headline:headline.slice(0,140),
      url:href?("https://pro.fiverr.com"+href):""
    });
  }
  return out;
})()

(function(){
  var q=function(s){var n=document.querySelector(s);return n?(n.innerText||"").replace(/\s+/g," ").trim():"";};
  var body=(document.body?document.body.innerText:"").replace(/\s+/g," ");
  var rm=body.match(/([0-9.]+)\s*\(([0-9,]+)\)/);
  var about=body.match(/About me\s+(.+?)(?:\s+(?:Portfolio|Skills|Reviews|Frequently|Languages)\b|$)/);
  var price=body.match(/(US\$[0-9,.]+\s*\/\s*(?:project|hour|hr))/i);
  var langs=body.match(/Languages?\s+([A-Za-z ,]+?)\s+(?:Vetted by|Claude|About me)/);
  return [{
    name:q("h1"),
    handle:(body.match(/@([A-Za-z0-9_]+)/)||[])[1]||"",
    rating:rm?rm[1]:"",
    reviews:rm?rm[2].replace(/,/g,""):"",
    badge:/Vetted Pro/.test(body)?"Vetted Pro":"",
    price:price?price[1]:"",
    about:about?about[1].slice(0,600):"",
    aboutLen:about?about[1].length:0,
    url:location.href
  }];
})()
